import { describe, expect, test } from 'vitest';

import * as maybe from 'true-myth/maybe';
import * as result from 'true-myth/result';
import * as task from 'true-myth/task';
import * as toolbelt from 'true-myth/toolbelt';

describe('iterable composition', () => {
  test('Maybe iterates, short-circuits iterable operations, and supports collection helpers', () => {
    expect([...maybe.just(1)]).toEqual([1]);
    expect([...maybe.nothing<number>()]).toEqual([]);

    let advanced = 0;
    function* items() {
      yield maybe.just(1);
      yield maybe.nothing<number>();
      advanced += 1;
      yield maybe.just(3);
    }
    expect(maybe.sequence(items())).toEqual(maybe.nothing());
    expect(advanced).toBe(0);
    expect(maybe.traverse([1, 2], (n) => maybe.just(n * 2))).toEqual(maybe.just([2, 4]));
    expect(maybe.traverse((n: number) => maybe.just(n))([1])).toEqual(maybe.just([1]));
    expect(maybe.zip(maybe.just(1), maybe.just('a'))).toEqual(maybe.just([1, 'a']));
    expect(maybe.zipWith(maybe.just(1), maybe.just(2), (a, b) => a + b)).toEqual(maybe.just(3));
    expect(maybe.compact([maybe.just(1), maybe.nothing<number>()])).toEqual([1]);
    expect(maybe.filterMap([1, 2], (n) => (n % 2 ? maybe.just(n) : maybe.nothing()))).toEqual([1]);
    expect(maybe.filterMap((n: number) => maybe.just(n))([1])).toEqual([1]);
    expect(maybe.firstJust([maybe.nothing<number>(), maybe.just(2)])).toEqual(maybe.just(2));
  });

  test('Result iterates, short-circuits, and partitions', () => {
    expect([...result.ok(1)]).toEqual([1]);
    expect([...result.err<number, string>('no')]).toEqual([]);
    expect(
      result.sequence([result.ok<number, string>(1), result.err<number, string>('no')])
    ).toEqual(result.err('no'));
    expect(result.traverse((n: number) => result.ok<number, string>(n))([1])).toEqual(
      result.ok([1])
    );
    expect(result.zip(result.ok<number, string>(1), result.ok<string, string>('a'))).toEqual(
      result.ok([1, 'a'])
    );
    expect(
      result.zipWith(result.ok<number, string>(1), result.ok<number, string>(2), (a, b) => a + b)
    ).toEqual(result.ok(3));
    expect(
      result.partition([result.ok<number, string>(1), result.err<number, string>('no')])
    ).toEqual([[1], ['no']]);
  });

  test('Task iterates as one Result and supports composition, taps, and retries', async () => {
    const resolved = task.resolve<number, string>(1);
    const rejected = task.reject<number, string>('no');
    const values = [] as result.Result<number, string>[];
    for await (const value of resolved) values.push(value);
    expect(values).toEqual([result.ok(1)]);
